    def _period_type(row: pd.Series) -> str:
        dd = row.get("duration_days")
        if dd is None or pd.isna(dd):
            return "Instant"
        return classify_duration(dd)

    def _build_facts_long() -> pd.DataFrame:
        if audit is None or audit.empty:
            return pd.DataFrame()
        base = audit.copy()
        base["period_end"] = base["quarter"]
        base["period_start"] = base["start"]
        base["period_type"] = base.apply(_period_type, axis=1)
        base["source_class"] = base["source"].apply(_source_class)
        base["method"] = base["source"].apply(_source_method)
        base["qa_severity"] = base["source"].apply(_source_qa)
        base["source_tier"] = base["source"].apply(_source_tier)
        base["source_type"] = base["source"]
        base["filed_date"] = base["filed"]
        base["doc_ref"] = base["note"]
        base["qa_flag"] = "pass"
        if needs_review is not None and not needs_review.empty:
            nr = needs_review.copy()
            nr["quarter"] = pd.to_datetime(nr["quarter"], errors="coerce")
            sev_map: Dict[Tuple[str, pd.Timestamp], str] = {}
            for _, r in nr.iterrows():
                key = (r.get("metric"), r.get("quarter"))
                sev = r.get("severity")
                if key not in sev_map or sev == "fail":
                    sev_map[key] = sev
            base["qa_flag"] = base.apply(
                lambda r: sev_map.get((r.get("metric"), pd.to_datetime(r.get("quarter"), errors="coerce")), "pass"),
                axis=1,
            )
        facts = base[[
            "metric",
            "period_end",
            "period_type",
            "value",
            "unit",
            "source_class",
            "method",
            "qa_severity",
            "source_tier",
            "source_type",
            "tag",
            "accn",
            "filed_date",
            "doc_ref",
            "qa_flag",
            "period_start",
            "form",
        ]].copy()
        return facts

